/**.
 * Relevant Documentation
 * The AST viewer is really helpful for figuring out the structure of the nodes: https://ts-morph.com/setup/ast-viewers
 * ts-morph docs: https://ts-morph.com/
 */

const fs = require('fs')
const { Project, CallExpression, StringLiteral, ObjectLiteralExpression, ExpressionStatement, Identifier } = require('ts-morph')
const { SyntaxKind } = require('typescript')
const exec = require('child_process').exec;
const del = require('del');

// traverseProject returns all of the string literals with mfe-utils| or global|
const values = traverseProject('./tsconfig.json');
const output = JSON.stringify(values, null, 2);
fs.writeFileSync('mfe-utils.message-keys.json', output, {encoding:'utf8'});
mergeInKeysFromMaster();

function traverseProject(configPath) {
  // Setup TS-Morph
  const project = new Project();

  // Resolve files via dependency resolution
  project.addSourceFilesFromTsConfig(configPath)
  project.resolveSourceFileDependencies();

  //We need to find all calls to translate and setTranslations.
  //Both of those are defined in the i18n.ts file so we look that file up.
  const i18nFile = project.getSourceFile('i18n.ts');

  //This map stores the message key/value pairs.
  const resultsMap = {};

  walkCallsToFunction(i18nFile, 'translate', (node) => {
    const stringLiterals = extractStringLiteralsFromTranslateCall(node);
    for (const key of stringLiterals) {
      resultsMap[key] = key.split('|').at(-1);
    }
  })

  walkCallsToFunction(i18nFile, 'setTranslations', (node) => {
    const translations = extractMappingFromSetTranslationsCall(node)
    
    Object.assign(resultsMap, translations);
  })

  // console.log(resultsMap);

  return resultsMap;
}

function walkCallsToFunction(file, functionName, callback) {
  const functionToSearchFor = file.getFunction(functionName);

  const referencesToFunctionCall = functionToSearchFor.findReferencesAsNodes();

  if (referencesToFunctionCall instanceof Array) {
    const calls = referencesToFunctionCall.map((node) => {
      return node.getParent();
    }).filter((node) => {
      return node instanceof CallExpression;
    });

    for (const call of calls) {
      callback(call);
    }
  }
}

function extractStringLiteralsFromTranslateCall(callNode) {
  if (callNode instanceof CallExpression) {
    const arguments = callNode.getArguments()

    if (arguments.length !== 1) {
      // If there are extra arguments, that means we passed in parameters for the translation.
      // We handle those cases specifically using the setTranslations calls.
      return []
    }

    const child = arguments[0]
    if (child instanceof StringLiteral) {
      // When it's a StringLiteral, we return its value.
      return [child.getLiteralValue()]
    } else {
      // Otherwise we return the values of the string literals it has as descendants.
      const literals = child.getDescendantsOfKind(SyntaxKind.StringLiteral)

      return literals.map(literal => literal.getLiteralValue())
    }
  } else {
    console.log('the node is not a CallExpression');
  }

  return []
}

function extractMappingFromSetTranslationsCall(callNode) {
  const mapping = {};

  if (callNode instanceof CallExpression) {
    const arguments = callNode.getArguments()

    const firstArgument = arguments[0]
    if (firstArgument instanceof ObjectLiteralExpression) {
      const propertyAssignments = firstArgument.getDescendantsOfKind(SyntaxKind.PropertyAssignment)
      for (const assign of propertyAssignments) {
        const keyNode = assign.getNameNode()
        const valNode = assign.getInitializer()

        let key, val

        if (keyNode instanceof StringLiteral) {
          key = keyNode.getLiteralValue()
        } else {
          key = keyNode
        }

        if (valNode instanceof StringLiteral) {
          val = valNode.getLiteralValue()
        }

        if (key && val) {
          mapping[key] = val;
        }
      }
    } else {
      // console.log("Found argument to setTranslations that wasn't an object literal.", firstArgument)
    }
  }

  return mapping
}


function mergeInKeysFromMaster() {
  exec('git show origin/master:mfe-utils.message-keys.json > mfe-utils.message-keys.master.json', function(err, stdout, stderr) {
    if (err != null || typeof(stderr) != 'string') {
        console.error('the git command did not work', err, stderr);
        return;
    }
  
    console.log('comparing master file to local file');
  
    // Read the contents of the first file
    const mastFileString = fs.readFileSync('mfe-utils.message-keys.master.json', 'utf8');
  
    // Read the contents of the second file
    const localFileString = fs.readFileSync('mfe-utils.message-keys.json', 'utf8');

    const isDifferent = mastFileString !== localFileString
  
    // Compare the contents of the files
    if(isDifferent) {
      
      //They are different. That means we need to make sure that any deleted message keys
      //will be added back in from the master file.
      const masterFileObj = JSON.parse(mastFileString);
      const localFileObj = JSON.parse(localFileString);
  
      const mergedContent = Object.assign(masterFileObj, localFileObj);
  
      console.log('merged in content from master');
      fs.writeFileSync('mfe-utils.message-keys.json', JSON.stringify(mergedContent, null, 2));
    }

    console.log('Updating message-keys-status.json');
    fs.writeFileSync('message-keys-status.json', JSON.stringify({
      messageKeysChangedSinceLastRelease: isDifferent
    }, null, 2));
  
    del.sync('mfe-utils.message-keys.master.json');
  });

}